#!/usr/bin/env python3
"""Apply debugging challenge prerequisites to DB."""
import base64, subprocess

def psql_update(slug: str, content: str):
    b64 = base64.b64encode(content.encode("utf-8")).decode("ascii")
    sql = (
        'UPDATE "Challenge" SET "starterSchema" = '
        f'convert_from(decode(\'{b64}\',\'base64\'),\'UTF8\') '
        f'WHERE slug = \'{slug}\' AND "starterSchema" IS NULL;'
    )
    result = subprocess.run(
        ["docker", "exec", "bitcode-postgres",
         "psql", "-U", "postgres", "-d", "bitcode", "-c", sql],
        capture_output=True, text=True
    )
    updated = "UPDATE 1" in result.stdout
    print(f"  {'OK  ' if updated else 'skip'} {slug}")

PREREQS_B64 = {
    "ai-autoscaling-queue": "",
    "ai-canary-deployment": "",
    "ai-inference-latency-alert": "",
    "api-error-boundary": "",
    "autocomplete-sensitive-fields": "",
    "cache-invalidation-mutation": "",
    "clickjacking-prevention": "",
    "client-validation-bypass-debug": "",
    "codebase-exploration-built-in-tools": "",
    "cookie-security-audit": "",
    "cors-spa-debug": "",
    "csp-violation-debug": "",
    "debug-auth-callback": "",
    "debug-high-llm-costs": "",
    "double-submit-prevention": "",
    "event-listener-accumulation": "",
    "file-upload-progress-debug": "",
    "frontend-infinite-scroll-debug": "",
    "frontend-perf-investigation": "",
    "jwt-storage-security": "",
    "llm-blue-green-deployment": "",
    "llm-error-rate-alert": "",
    "llm-service-health-monitoring": "",
    "memory-leak-intervals": "",
    "mixed-content-debug": "",
    "nextjs-hydration-mismatch": "",
    "nextjs-rsc-cache-bug": "",
    "oauth-pkce-frontend": "",
    "observability-sse-memory-leak": "",
    "open-redirect-spa": "",
    "optimistic-update-rollback": "",
    "pagination-off-by-one": "",
    "prototype-pollution-fix": "",
    "race-condition-fetch-stale": "",
    "react-key-prop-debug": "",
    "stale-closure-useeffect": "",
    "token-budget-enforcement": "",
    "useeffect-infinite-loop": "",
    "websocket-reconnect-debug": "",
    "xss-react-user-content": "",
}

PREREQS = {k: base64.b64decode(v).decode("utf-8") for k, v in PREREQS_B64.items()}

print(f"Applying {len(PREREQS)} debugging prerequisites...")
for slug, content in PREREQS.items():
    psql_update(slug, content)
print("\nDone.")
